actions.script:
const current = ec.service.sync().name('ironstone.projects.WorkItemImportServices.get#ImportDraft').parameters({importId: importId}).call()
if (!current?.found) { ec.message.addError(ec.l10n.localize('This import is not available; start again from the file')); return }
if (!current.draft.options) { ec.message.addError(ec.l10n.localize('Choose the options first')); return }
ec.service.sync().name('ironstone.projects.WorkItemImportServices.store#ImportDraft').parameters({importId: importId, fields: {status: 'previewed'}}).call()

const L = (text) => ec.l10n.localize(text)
const current = ec.service.sync().name('ironstone.projects.WorkItemImportServices.get#ImportDraft').parameters({importId: importId}).call() || {}
hasDraft = !!current.found
previewRows = []
if (!hasDraft) return
const draft = current.draft
const options = draft.options || {}
const out = ec.service.sync().name('mantle.work.WorkItemImportServices.preview#WorkItems').parameters({fileLocation: current.fileLocation,
    presetId: draft.presetId, columnMapping: draft.columnMapping || null, valueMaps: draft.valueMaps || null, estimateUnit: draft.estimateUnit || null,
    rootWorkEffortId: draft.rootWorkEffortId, createMissing: options.createMissing !== false, existingPolicy: options.existingPolicy || 'skip', maxRows: 50}).call()
if (ec.message.hasError()) { previewError = ec.message.getErrorsString(); ec.message.clearErrors(); hasDraft = false; return }
const actions = {create: L('Create'), update: L('Update'), skip: L('Skip'), fail: L('Fails')}
const styles = {create: 'text-positive', update: 'text-primary', skip: 'm-muted', fail: 'text-negative'}
const enumLabel = (id) => id ? (ec.entity.find('moqui.basic.Enumeration').condition('enumId', id).useCache(true).one()?.description || id) : ''
const statusLabel = (id) => id ? (ec.entity.find('moqui.basic.StatusItem').condition('statusId', id).useCache(true).one()?.description || id) : ''
const planText = (plan) => plan ? plan.name + (plan.make ? ' (' + L('new') + ')' : '') : ''
previewRows = Array.from(out.previewList || []).map((row) => ({rowNumber: row.rowNumber, key: row.key || '', title: row.title || L('(no title)'),
    typeText: enumLabel(row.purposeEnumId) + ' · ' + row.priority, statusText: statusLabel(row.statusId), assigneeText: row.assigneeName || '',
    parentText: row.parentKey || '', planText: [planText(row.sprint), planText(row.release), planText(row.milestone)].filter((part) => part).join(', '),
    actionLabel: actions[row.action] || row.action, actionStyle: styles[row.action] || '',
    problemText: Array.from(row.problems || []).concat(Array.from(row.warnings || [])).join('; '), problemStyle: (row.problems || []).length ? 'text-negative' : 'text-warning'}))
const counts = out.counts || {}
summaryText = ec.resource.expand('${rows} rows: ${create} to create, ${update} to update, ${skip} to skip, ${fail} failing, ${warned} with warnings', '',
        {rows: counts.rows || 0, create: counts.create || 0, update: counts.update || 0, skip: counts.skip || 0, fail: counts.fail || 0, warned: counts.warned || 0})
moreRows = Number(counts.rows || 0) > previewRows.length
